"""Unit tests for `worlds.make`: name and variant lookup, errors and override forwarding.

The world classes are separate tasks, so these tests stand them in with small classes that
record what `make` passed them; the spec is set in `__init__`, as a real world sets it.
"""

import pytest

from rllab.core.types import Discrete, TeamSpec, WorldSpec
from rllab.worlds import make as make_module
from rllab.worlds.make import make


def _stand_in(name: str) -> type:
    class StandIn:
        def __init__(self, **overrides: int | float) -> None:
            unknown = set(overrides) - {"size"}
            if unknown:
                raise ValueError(f"unknown override {sorted(unknown)[0]!r}")
            self.overrides = overrides
            self.spec = WorldSpec(
                world=name,
                variant="default",
                agents=("a0",),
                teams=(TeamSpec("t", (0,), "score", "higher"),),
                obs_len=4,
                action=Discrete(3),
                max_steps=10,
                measures=(),
                sight=None,
            )

    return StandIn


@pytest.fixture(autouse=True)
def stand_ins(monkeypatch: pytest.MonkeyPatch) -> None:
    monkeypatch.setattr(make_module, "Snake", _stand_in("snake"))
    monkeypatch.setattr(make_module, "CheckDiscrete", _stand_in("check-discrete"))


@pytest.mark.parametrize("world", ["snake", "check-discrete"])
def test_make_returns_the_named_world_with_spec_before_reset(world: str) -> None:
    built = make(world)
    assert type(built) is getattr(make_module, "Snake" if world == "snake" else "CheckDiscrete")
    assert built.spec.world == world


def test_make_accepts_default_variant_explicitly() -> None:
    assert make("snake", "default").spec.world == "snake"


def test_make_forwards_overrides_to_the_world() -> None:
    built = make("snake", size=12)
    assert getattr(built, "overrides") == {"size": 12}


def test_make_unknown_world_names_it() -> None:
    with pytest.raises(ValueError, match="'tetris'"):
        make("tetris")


def test_make_unknown_variant_names_it() -> None:
    with pytest.raises(ValueError, match="'many'"):
        make("snake", "many")


def test_make_unknown_variant_raises_before_building() -> None:
    with pytest.raises(ValueError, match="'check-discrete'"):
        make("check-discrete", "wide")


def test_make_passes_on_the_world_error_for_an_unknown_override() -> None:
    with pytest.raises(ValueError, match="'speed'"):
        make("snake", speed=2)

